create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ac200000-0000-0000-0000-000000000001',true);
select pg_temp.ok(has_permission('DISPATCH_VIEW') and has_permission('APPROVAL_VIEW') and has_permission('QUALITY_WRITE') and has_permission('QUALITY_DAILY_REVIEW'),'laboratory supervisor receives missing operational permissions');
select pg_temp.ok(not has_permission('ACCESS_ADMIN'),'laboratory supervisor cannot administer accounts');
select pg_temp.denied($q$select lab_operation('ac100000-0000-0000-0000-000000000002','DEVICE','{}')$q$,'laboratory write rejects foreign branch');
select lab_operation('ac100000-0000-0000-0000-000000000001','DEVICE','{"code":"LAB-COLD","type":"NEVERA","location":"Prueba","min_temp":2,"max_temp":6}');
select lab_operation('ac100000-0000-0000-0000-000000000001','TEMPERATURE',jsonb_build_object('device_id',(select id from cold_chain_devices where device_code='LAB-COLD'),'value',9,'evidence','LECTURA'));
select pg_temp.ok((select count(*)=1 from cold_chain_readings),'supervisor can record temperature without another application role');
select pg_temp.denied($q$update cold_chain_devices set min_temp=10,max_temp=2 where device_code='LAB-COLD'$q$,'direct writes cannot create invalid thermal limits');
select lab_operation('ac100000-0000-0000-0000-000000000001','METHOD_VERIFY','{"code":"LAB-VER","method_id":"ac400000-0000-0000-0000-000000000001","parameters":"Parámetros ficticios","criteria":"Criterio aprobado ficticio","summary":"Resultados ficticios","conclusion":"Cumple","result":"ACEPTADO","evidence":"REF-METODO"}');
select pg_temp.denied($q$update lab_methods set status='APROBADO' where method_code='LAB-M'$q$,'method executor cannot bypass independent approval');
select set_config('request.jwt.claim.sub','ac200000-0000-0000-0000-000000000002',true);
select lab_operation('ac100000-0000-0000-0000-000000000001','METHOD_APPROVE',(select jsonb_build_object('id',id,'before',to_jsonb(v),'evidence','REV-METODO') from method_verifications v where verification_code='LAB-VER'));
select pg_temp.ok((select status='APROBADO' from lab_methods where method_code='LAB-M'),'method preparation completes through independent documented approval');
select set_config('request.jwt.claim.sub','ac200000-0000-0000-0000-000000000001',true);
select lab_operation('ac100000-0000-0000-0000-000000000001','IQC_PLAN','{"code":"LAB-PLAN","method_id":"ac400000-0000-0000-0000-000000000001","control_name":"Control","control_lot":"LOT","lower_limit":2,"upper_limit":6,"frequency":"Por turno"}');
select lab_operation('ac100000-0000-0000-0000-000000000001','IQC_RESULT',jsonb_build_object('plan_id',(select id from iqc_plans where plan_code='LAB-PLAN'),'value',9,'evidence','REF-QC'));
select pg_temp.ok((select result_status='FUERA_CONTROL' from iqc_results),'out-of-range IQC uses configured limits and is not accepted');
select lab_operation('ac100000-0000-0000-0000-000000000001','REAGENT',jsonb_build_object('code','LAB-R','name','Reactivo ficticio','lot','L1','expiry_date',current_date+60,'quantity',10,'unit','Pruebas','evidence','REF-LOTE'));
select pg_temp.ok((select verification_status='PENDIENTE' and entered_by=auth.uid() from reagent_lots where reagent_code='LAB-R'),'new lots stay pending with server-attributed author');
select pg_temp.denied($q$update reagent_lots set verification_status='APROBADO' where reagent_code='LAB-R'$q$,'lot author cannot self approve through direct table update');
select pg_temp.denied($q$delete from lab_event_log$q$,'audit cannot be deleted by laboratory supervisor');
select lab_operation('ac100000-0000-0000-0000-000000000001','EQA_EVENT',jsonb_build_object('code','LAB-EVT','program_id','ac500000-0000-0000-0000-000000000001','cycle','2026','due_date',current_date+30));
select lab_operation('ac100000-0000-0000-0000-000000000001','EQA_RESULT',(select jsonb_build_object('id',id,'before',to_jsonb(e),'result','NO_SATISFACTORIO','evidence','REF-EQA') from eqa_events e where event_code='LAB-EVT'));
select pg_temp.ok((select investigation_required and status='EVALUADO' from eqa_events where event_code='LAB-EVT'),'unsatisfactory EQA requires investigation and never auto closes');
select pg_temp.denied($q$select lab_operation('ac100000-0000-0000-0000-000000000001','EQA_RESULT',(select jsonb_build_object('id',id,'before','{}'::jsonb,'result','SATISFACTORIO','evidence','REF') from eqa_events where event_code='LAB-EVT'))$q$,'stale EQA snapshot cannot overwrite results');
select lab_operation('ac100000-0000-0000-0000-000000000001','SERVICE',jsonb_build_object('code','LAB-SRV','equipment_id','ac300000-0000-0000-0000-000000000001','event_type','CALIBRACION','performed_date',current_date,'next_due_date',current_date+30,'provider','Proveedor ficticio','result','NO_CONFORME','evidence','CERT','findings','Fuera de criterio'));
select pg_temp.ok((select status='FUERA_SERVICIO' from lab_equipment where equipment_code='LAB-EQ'),'nonconforming service removes instrument from service');
