select lab_operation('ac100000-0000-0000-0000-000000000001','TRANSPORT_RECEIVE',(select jsonb_build_object('id',id,'value',10,'condition','CONFORME','evidence','RECEPCION') from transport_events where transport_code='LAB-T'));
select pg_temp.ok((select status='CUARENTENA' from transport_events where transport_code='LAB-T'),'out-of-range arrival is quarantined even if user marks reception conforming');
