insert into screening_tests(screening_code,source_unit_code,branch_id,test_type,result) values('LAB-S2','LAB-U','ac100000-0000-0000-0000-000000000001','Repetición ficticia','REACTIVO');
select pg_temp.ok((select inventory_status='CUARENTENA' from blood_inventory_units where unit_code='LAB-COMP'),'new unresolved test places available unit back in quarantine');
select pg_temp.denied($q$select review_and_release_unit('LAB-U','APTO','Revisión','REF')$q$,'reactive or pending test blocks release after earlier approval');
select pg_temp.ok((select count(*)>10 from lab_event_log),'clinical operations retain immutable before and after audit');
select set_config('request.jwt.claim.sub','ac200000-0000-0000-0000-000000000003',true);
select pg_temp.denied($q$select lab_operation('ac100000-0000-0000-0000-000000000001','DEVICE','{}')$q$,'read-only role cannot record laboratory operations');
reset role;
update profiles set active=false where id='ac200000-0000-0000-0000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','ac200000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select lab_operation('ac100000-0000-0000-0000-000000000001','DEVICE','{}')$q$,'inactive actor cannot use laboratory API');
reset role;set local role anon;
select pg_temp.denied($q$select lab_operation('ac100000-0000-0000-0000-000000000001','DEVICE','{}')$q$,'anonymous cannot invoke laboratory API');
rollback;
